import {scout} from './lib/engine.js';
import {MockPreferenceInterpreter} from './lib/preferences.js';
import {MockFlightProvider,MockHotelProvider} from './lib/providers.js';
const form=document.querySelector('form'),output=document.querySelector('#results');
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const date=d=>new Date(d+'T00:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let result,selected;
function render(){
 const {trip:t,best:b,decision:d,candidates:cs,preferences:p}=result;
 const reason=!b?'No hotels or flights meet your rating and flight requirements. Try a lower minimum rating or remove the nonstop requirement.':d==='WAIT'?'No date fits both budgets. Increase a budget or explore a different window. This is not a forecast of falling prices.':d==='CHANGE DATE'?`Moving from ${date(t.start)} ${result.savings>0?`saves ${money(result.savings)}`:'brings the trip within your limits'}. This option meets your flight budget, hotel budget, and minimum rating.`:'This is your highest-scoring qualifying option. It meets both budgets and your minimum hotel rating.';
 const title=!b?'No matching stays this time.':d==='WAIT'?'A better fit is worth finding.':d==='CHANGE DATE'?`A small shift. A smarter trip.`:'Your trip has a green light.';
 const max=Math.max(...cs.map(c=>c.total),1);
 output.innerHTML=`<article class="recommendation"><div class="rec-inner"><div class="rec-top"><span class="badge ${d==='WAIT'?'wait':d==='CHANGE DATE'?'change':''}">${d}</span><span>SCOUT RECOMMENDATION</span></div><h3>${title}</h3><p>${reason}</p>${b?`<div class="rec-bottom"><div><small>${d==='WAIT'?'Top scored option':'Recommended dates'}</small><strong>${date(b.date)} – ${date(b.returnDate)}</strong></div><div><small>Flight + ${t.nights} nights</small><strong>${money(b.total)}</strong></div><div><small>${b.total<=t.flightBudget+t.hotelBudget*t.nights?'Under total budget':'Over total budget'}</small><strong>${money(Math.abs(t.flightBudget+t.hotelBudget*t.nights-b.total))}</strong></div></div>`:''}</div></article><div class="total-row"><div><h3>Timing makes a difference</h3><p>${result.checked} departure dates · ${escape(t.origin)} → ${escape(t.destination)}</p></div><div class="legend"><span><i></i>Flight</span><span><i></i>Hotel</span></div></div>${cs.length?`<div class="chart" aria-label="Total trip cost by departure date">${cs.map(c=>`<button class="bar-col ${c.date===selected?'active':''}" data-date="${c.date}" aria-label="Inspect ${date(c.date)}, ${money(c.total)}"><strong>${money(c.total)}</strong><span class="bar" style="height:${Math.round(c.total/max*100)}px"><b style="height:${c.flight.price/c.total*100}%"></b></span><span>${date(c.date)}</span></button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>DEPARTURE</th><th>FLIGHT</th><th>HOTEL / NIGHT</th><th>TOTAL</th><th>FIT SCORE</th></tr></thead><tbody>${cs.map(c=>`<tr class="${c.date===selected?'selected':''}"><td><button class="row-button" data-date="${c.date}">${date(c.date)} – ${date(c.returnDate)}</button><small>${c.date===b.date&&b.feasible?'✦ Recommended':c.feasible?'Within budgets':'Over budget'}</small></td><td>${money(c.flight.price)}<small>${c.flight.stops?'1 stop':'Nonstop'}</small></td><td>${money(c.hotel.nightly)}<small>★ ${c.hotel.rating} guest rating</small></td><td><strong>${money(c.total)}</strong></td><td><span class="score">${c.score} / 100</span></td></tr>`).join('')}</tbody></table></div><div class="selection">${detail(cs.find(c=>c.date===selected)||b,t)}</div>`:'<div class="empty">No matching options. Update your trip preferences and scout again.</div>'}<p class="hint" style="margin:16px 0 0">Applied: ${p.priority==='comfort'?'comfort priority':'best value'}${p.nonstop?' · nonstop only':''} · Local preference simulator · Synthetic quotes</p>`;
 output.querySelectorAll('[data-date]').forEach(el=>el.addEventListener('click',()=>{selected=el.dataset.date;render()}));
}
function detail(c,t){return `<h3>${escape(c.hotel.name)} · ${date(c.date)} – ${date(c.returnDate)}</h3><p>Round-trip flight ${money(c.flight.price)} + hotel ${money(c.hotel.nightly)} × ${t.nights} nights = <strong>${money(c.total)}</strong>.<br>${c.flight.price>t.flightBudget?`Flight exceeds budget by ${money(c.flight.price-t.flightBudget)}.`:'Flight budget met.'} ${c.hotel.nightly>t.hotelBudget?`Hotel exceeds nightly budget by ${money(c.hotel.nightly-t.hotelBudget)}.`:'Hotel budget met.'} Guest rating ${c.hotel.rating}/5.</p>`}
async function run(example=false){const button=document.querySelector('#submit');button.disabled=true;button.innerHTML='Comparing your dates…';document.querySelector('#error').textContent='';try{const t=Object.fromEntries(new FormData(form));for(const k of ['nights','flightBudget','hotelBudget','rating'])t[k]=Number(t[k]);result=await scout(t,new MockPreferenceInterpreter(),new MockFlightProvider(),new MockHotelProvider());selected=result.best?.date;render();document.querySelector('#result-meta').textContent=example?'EXAMPLE SEARCH':'SEARCH COMPLETE';document.querySelector('#stale').hidden=true;}catch(e){document.querySelector('#error').textContent=e.message;}finally{button.disabled=false;button.innerHTML='Scout my dates <span>↗</span>';}}
form.addEventListener('submit',e=>{e.preventDefault();run()});form.addEventListener('input',()=>{document.querySelector('#stale').hidden=false});run(true);
